INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning) VALUES ('beiliao-founded', '北辽建立', 'politics', 'point', 'day', '保大二年三月癸酉，1122年4月22日，于南京称帝，改元建福', 1122, 4, 13467, NULL, NULL, NULL, NULL, NULL, NULL, '金军攻辽，耶律淳于燕京称帝，国号北辽，旋即覆灭。', NULL)
