INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning) VALUES ('dongliao-founded', '东辽建立', 'politics', 'point', 'month', '贞祐四年三月，部众推耶律留哥为辽王，改元天统', 1213, 3, 14558, NULL, NULL, NULL, NULL, NULL, NULL, '耶律留哥于辽东称辽王，定国号辽，改元天统，史称东辽；众人劝进称帝，留哥拒绝。', NULL)
